// ===== ВАЛИДАЦИЯ, ЛИМИТЫ, ИДЕМПОТЕНТНОСТЬ, ВЫКЛЮЧАТЕЛЬ =====
const MAX_INPUT_CHARS = 2000;          // лимит размера входа
const MAX_ORDERS_PER_HOUR = 20;        // лимит обращений на один контакт
const PRICE_RUB_PER_1K_TOKENS = 0.60;  // ПРОВЕРЬ актуальный прайс Yandex AI Studio
const EST_OUTPUT_TOKENS = 400;
const SYSTEM_PROMPT_TOKENS = 300;

function hash32(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, '0');
}

const t0 = Date.now();

// Ручной выключатель: строка orders_enabled в таблице настроек.
// Если настройки недоступны — работаем (fail-open). Для платёжных сценариев
// разумнее обратное решение, но тогда падение справочника останавливает бизнес.
const settingsRow = $('NocoDB: настройки').first().json ?? {};
const rawFlag = settingsRow.value;
const processing_enabled = rawFlag === undefined
  ? true
  : !['false', '0', 'off', 'no'].includes(String(rawFlag).toLowerCase());

const out = [];

for (const item of $('Приём заказа').all()) {
  const body = item.json.body ?? {};
  const headers = item.json.headers ?? {};

  const errors = [];

  // --- типы и обязательные поля ---
  if (body.text !== undefined && typeof body.text !== 'string') errors.push('text_must_be_string');
  if (body.qty !== undefined && typeof body.qty !== 'number') errors.push('qty_must_be_number');

  const customer = String(body.customer ?? '').trim();
  const contact = String(body.contact ?? '').trim().toLowerCase();
  const text = String(body.text ?? '').replace(/\r\n/g, '\n').trim();
  const client_order_id = body.order_id ? String(body.order_id).trim() : null;

  if (!customer) errors.push('customer_required');
  if (!contact) errors.push('contact_required');
  if (!text) errors.push('text_required');

  // --- лимит размера входа: до вызова модели, а не после ---
  if (text.length > MAX_INPUT_CHARS) errors.push('input_too_large');

  // --- защита от циклов: сценарий не должен вызывать сам себя ---
  const depth = Number(headers['x-loop-depth'] ?? 0);
  if (depth > 0) errors.push('loop_detected');

  // --- ключ идемпотентности ---
  const headerKey = headers['idempotency-key'] ?? headers['Idempotency-Key'];
  const derived = hash32(contact + '|' + text.toLowerCase().replace(/\s+/g, ' '));
  const idempotency_key = String(headerKey ?? '').trim() || derived;
  const key_source = headerKey ? 'client' : 'derived';

  const received_at = new Date().toISOString();
  const order_id = client_order_id
    || 'ORD-' + received_at.slice(0, 10).replace(/-/g, '') + '-' + hash32(idempotency_key).toUpperCase();

  // --- предварительная оценка стоимости запуска ---
  const est_input_tokens = Math.ceil(text.length / 3) + SYSTEM_PROMPT_TOKENS;
  const est_total_tokens = est_input_tokens + EST_OUTPUT_TOKENS;
  const est_cost_rub = Number((est_total_tokens / 1000 * PRICE_RUB_PER_1K_TOKENS).toFixed(4));

  if (!processing_enabled) errors.push('processing_disabled');

  const can_process = errors.length === 0;

  const http_code = errors.includes('processing_disabled') ? 503
    : errors.includes('input_too_large') ? 413
    : errors.includes('loop_detected') ? 508
    : 422;

  // Вход для агента собираем здесь же — отдельная нода не нужна.
  const agent_input = [
    '<<<ЗАКАЗ_НАЧАЛО>>>',
    'Клиент: ' + customer,
    'Текст заказа:',
    text,
    '<<<ЗАКАЗ_КОНЕЦ>>>',
  ].join('\n');

  out.push({ json: {
    order_id, idempotency_key, key_source, received_at, agent_input,
    customer, customer_contact: contact, text, text_length: text.length,
    can_process, errors, http_code,
    est_total_tokens, est_cost_rub,
    max_orders_per_hour: MAX_ORDERS_PER_HOUR,
    price_per_1k: PRICE_RUB_PER_1K_TOKENS,
    t0,
    stages: [{ stage: 'validate', status: can_process ? 'ok' : 'rejected', ms: Date.now() - t0 }],
    // Единая форма ответа: у сценария одна нода Respond на все исходы.
    api_response: { status: 'rejected', order_id, errors },
  } });
}

return out;

// Режим: Run Once for All Items.
// На вход приходят строки из NocoDB (может быть 0 — нода стоит с Always Output Data).
// Сценарий обрабатывает один заказ за запуск, поэтому исходные данные берём через .first().
const t = $('Валидация и лимиты').first().json;

const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && (r.Id || r.id || r.order_id));

// 1. Идемпотентность: точное совпадение ключа = этот заказ уже обрабатывали.
const dup = rows.find((r) => String(r.idempotency_key) === String(t.idempotency_key));

// 2. Лимит обращений: сколько заказов от этого контакта за последний час.
const hourAgo = Date.now() - 3600 * 1000;
const recent = rows.filter((r) => {
  const ts = Date.parse(r.received_at);
  return Number.isFinite(ts) && ts > hourAgo;
});
const rate_exceeded = recent.length >= t.max_orders_per_hour;

const is_duplicate = Boolean(dup);

return [{ json: {
  ...t,
  is_duplicate,
  rate_exceeded,
  orders_last_hour: recent.length,
  previous_order_id: dup ? (dup.order_id ?? null) : null,
  previous_status: dup ? (dup.status ?? null) : null,
  previous_result: dup ? (dup.result_json ?? null) : null,
  can_call_model: !is_duplicate && !rate_exceeded,
  http_code: 200,
  api_response: {
    status: is_duplicate ? 'duplicate' : 'rate_limited',
    order_id: t.order_id,
    previous_order_id: dup ? (dup.order_id ?? null) : null,
    previous_status: dup ? (dup.status ?? null) : null,
    orders_last_hour: recent.length,
  },
  stages: [...t.stages, {
    stage: 'dedup',
    status: is_duplicate ? 'duplicate' : (rate_exceeded ? 'rate_limited' : 'ok'),
    ms: Date.now() - t.t0,
  }],
} }];

// Режим: Run Once for All Items.
// ===== ПРОВЕРКА ОТВЕТА МОДЕЛИ + ДЕТЕРМИНИРОВАННЫЙ РАСЧЁТ ДЕНЕГ =====
// Прайс живёт в коде. Модель не считает суммы — она только извлекает позиции.
const PRICE_LIST = {
  'FLT-100': { name: 'Фильтр масляный', price: 890 },
  'FLT-200': { name: 'Фильтр воздушный', price: 640 },
  'OIL-5W40': { name: 'Масло моторное 5W-40, 4 л', price: 3200 },
  'BRK-310': { name: 'Колодки тормозные передние', price: 4150 },
};
const URGENCY = ['normal', 'urgent'];
const URGENT_SURCHARGE = 0.15;

const t = $('Валидация и лимиты').first().json;
const res = $input.first().json ?? {};

let llm_ok = true;
let error_code = null;
let error_message = '';
let parsed = null;

// Агент отдаёт объект (с Output Parser), строку (без него)
// или объект с полем error (если упал и настроен на continueErrorOutput).
let raw = res.output ?? res;

if (raw && typeof raw === 'object' && !Array.isArray(raw) && !('items' in raw)) {
  // это не результат разбора — значит ошибка
  const e = raw.error ?? raw.message ?? null;
  if (e) {
    llm_ok = false;
    error_message = String(typeof e === 'object' ? JSON.stringify(e) : e).slice(0, 500);
    error_code = /timeout|ETIMEDOUT|ESOCKETTIMEDOUT/i.test(error_message) ? 'llm_timeout'
      : /401|403|Api-Key|unauthor/i.test(error_message) ? 'llm_auth_error'
      : /429|rate|quota/i.test(error_message) ? 'llm_rate_limited'
      : 'llm_unavailable';
    raw = null;
  }
}

if (llm_ok) {
  if (typeof raw === 'string') {
    const clean = raw.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
    try { parsed = JSON.parse(clean); } catch (e) { llm_ok = false; error_code = 'llm_bad_format'; error_message = 'invalid json'; }
  } else if (raw && typeof raw === 'object') {
    parsed = raw;
  } else {
    llm_ok = false; error_code = 'llm_bad_format'; error_message = 'empty output';
  }
  if (llm_ok && !Array.isArray(parsed?.items)) {
    llm_ok = false; error_code = 'llm_bad_format'; error_message = 'items is not an array';
  }
}

const p = parsed ?? {};

// Нормализация позиций
const items = [];
const unknown_items = [];
for (const raw of (Array.isArray(p.items) ? p.items : []).slice(0, 50)) {
  const sku = raw && raw.sku ? String(raw.sku).trim().toUpperCase() : null;
  const name = String(raw?.name ?? '').trim().slice(0, 120);
  let qty = Number(raw?.qty);
  if (!Number.isFinite(qty) || qty < 1) qty = 1;
  qty = Math.min(Math.floor(qty), 999);

  const known = sku && PRICE_LIST[sku];
  if (known) {
    items.push({ sku, name: known.name, qty, price: known.price, sum: known.price * qty });
  } else {
    unknown_items.push({ sku, name, qty });
  }
}

const urgency = URGENCY.includes(p.urgency) ? p.urgency : 'normal';
const delivery_address = String(p.delivery_address ?? '').trim().slice(0, 300);

// Деньги считает код
const subtotal = items.reduce((s, i) => s + i.sum, 0);
const surcharge = urgency === 'urgent' ? Math.round(subtotal * URGENT_SURCHARGE) : 0;
const total_rub = subtotal + surcharge;

const needs_review = !llm_ok || unknown_items.length > 0 || items.length === 0 || !delivery_address;
const status = !llm_ok ? 'failed' : (needs_review ? 'needs_review' : 'done');

// Агент не отдаёт usage наружу — оцениваем по факту длины.
const tokens = llm_ok ? Math.ceil((t.text.length + JSON.stringify(parsed).length) / 3) + 300 : null;
const cost_rub = tokens ? Number((tokens / 1000 * t.price_per_1k).toFixed(4)) : null;

// Payload для ручного перезапуска. Тот же ключ идемпотентности — повтор безопасен.
const retry_payload = llm_ok ? '' : JSON.stringify({
  customer: t.customer, contact: t.customer_contact, text: t.text,
  order_id: t.order_id, idempotency_key: t.idempotency_key,
});

const alert_text = llm_ok ? '' : [
  '🔴 <b>Заказ не обработан</b>',
  '<code>' + t.order_id + '</code>',
  '',
  '<b>Этап:</b> разбор заказа моделью',
  '<b>Код:</b> ' + error_code,
  '<b>Детали:</b> ' + error_message.slice(0, 200),
  '',
  'Входные данные сохранены. Перезапуск тем же ключом идемпотентности безопасен.',
].join('\n');

return [{ json: {
  ...t,
  agent_input: undefined,
  llm_ok, error_code, error_message, retry_payload, alert_text,
  http_code: llm_ok ? 200 : 502,
  api_response: llm_ok
    ? { status: status, order_id: t.order_id, total_rub, needs_review, cost_rub }
    : { status: 'failed', order_id: t.order_id, error_code, retry_safe: true },
  items, unknown_items, delivery_address, urgency,
  subtotal, surcharge, total_rub,
  items_json: JSON.stringify(items),
  unknown_json: unknown_items.length ? JSON.stringify(unknown_items) : '',
  needs_review, status,
  tokens_used: tokens, cost_rub,
  model_version: res?.result?.modelVersion ?? null,
  stages: [...t.stages,
    { stage: 'llm', status: llm_ok ? 'ok' : 'failed', ms: Date.now() - t.t0, tokens, cost_rub, error: error_code },
    { stage: 'parse', status: llm_ok ? (needs_review ? 'needs_review' : 'ok') : 'skipped', ms: Date.now() - t.t0 },
  ],
} }];

// Режим: Run Once for All Items.
// ЖУРНАЛ. Одна строка на этап. Только метаданные.
//
// ЧЕГО ЗДЕСЬ НЕТ И БЫТЬ НЕ ДОЛЖНО:
//   — текст заказа и любые пользовательские тексты
//   — контакт, имя, адрес доставки (персональные данные)
//   — содержимое ответа модели
//   — ключи, токены, значения credentials
// Журнал нужен, чтобы понять ЧТО и КОГДА сломалось, а не ЧТО написал клиент.
const t = $input.first().json;
const run_id = $execution.id;

return (t.stages ?? []).map((s) => ({ json: {
  ts: new Date().toISOString(),
  run_id: String(run_id),
  order_id: t.order_id,
  stage: s.stage,
  status: s.status,
  duration_ms: s.ms ?? null,
  tokens: s.tokens ?? null,
  cost_rub: s.cost_rub ?? null,
  error: s.error ?? t.error_code ?? '',
} }));
